display.text:
:root {
  --ink-0: #07090c;
  --ink-1: #0d1117;
  --ink-2: #151b23;
  --line: #2a3441;
  --line-strong: #46566a;
  --text: #e8edf2;
  --muted: #9ba8b8;
  --cost: #ffbf47;
  --queued: #8793a1;
  --running: #43b9ff;
  --done: #57d38c;
  --failed: #ff6470;
  --timeout: #c995ff;
  --unknown: #aab3be;
  --sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SFMono-Regular", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--ink-0);
  color-scheme: dark;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  background: var(--ink-0);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14px;
}

button,
input,
select,
textarea,
summary {
  font: inherit;
}

button,
summary {
  min-height: 36px;
}

button {
  border: 1px solid var(--line-strong);
  border-radius: 3px;
  background: var(--ink-2);
  color: var(--text);
  cursor: pointer;
}

button:hover:not(:disabled),
summary:hover {
  border-color: var(--text);
  background: #1b2430;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible,
a:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--running);
  outline-offset: 2px;
}

[hidden] {
  display: none !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-shell {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  height: 100dvh;
  min-width: 0;
}

.command-rail {
  z-index: 10;
  display: grid;
  grid-template-columns: minmax(190px, 1.1fr) minmax(250px, 1.8fr) minmax(220px, 1.4fr) minmax(260px, 1.4fr);
  min-height: 86px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--ink-1);
}

.command-rail > * {
  min-width: 0;
  padding: 12px 16px;
  border-right: 1px solid var(--line);
}

.command-rail > *:last-child {
  border-right: 0;
}

.eyebrow,
.metric-label,
dt {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin: 2px 0 8px;
  font-family: var(--mono);
  font-size: 18px;
  letter-spacing: 0.08em;
}

h2 {
  margin: 2px 0 0;
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.04em;
}

h3 {
  margin: 20px 0 8px;
  color: var(--running);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rail-status-line,
.inline-state {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 11px;
}

.state-badge,
.readonly-badge,
.provenance,
.selected-label {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 2px 6px;
  border: 1px solid currentColor;
  border-radius: 2px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.state-live {
  color: var(--done);
}

.state-connecting,
.state-reconnecting {
  color: var(--running);
}

.state-offline {
  color: var(--failed);
}

.rail-metric {
  display: grid;
  grid-template-columns: 1fr auto;
  align-content: center;
  gap: 3px 10px;
}

.rail-metric .metric-label {
  grid-column: 1 / -1;
}

.metric-value {
  align-self: center;
  overflow-wrap: anywhere;
  font-family: var(--mono);
  font-size: clamp(14px, 1.45vw, 24px);
  font-weight: 750;
  line-height: 1.08;
  text-align: left;
}

.cost-value {
  color: var(--cost);
  font-variant-numeric: tabular-nums;
}

.provenance {
  align-self: center;
  color: var(--cost);
  white-space: nowrap;
}

.burn-trace {
  grid-column: 1 / -1;
  width: 100%;
  height: 22px;
  overflow: visible;
}

.cost-line {
  fill: none;
  stroke: var(--cost);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.rail-counters {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: center;
  gap: 10px 16px;
}

.rail-counters div {
  display: grid;
  gap: 2px;
}

.rail-counters strong {
  overflow: hidden;
  color: var(--text);
  font-family: var(--mono);
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
}

.workspace {
  display: grid;
  grid-template-columns: minmax(260px, 5fr) minmax(300px, 5fr) minmax(190px, 2.5fr);
  min-height: 0;
  min-width: 0;
}

.pane {
  min-width: 0;
  min-height: 0;
  border-right: 1px solid var(--line-strong);
  background: var(--ink-1);
}

.pane:last-child {
  border-right: 0;
}

.pane-header {
  z-index: 2;
  min-width: 0;
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
  background: var(--ink-1);
}

.fleet-pane {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
}

.fleet-header,
.control-header,
.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.last-update {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  white-space: nowrap;
}

.fleet-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 9px 12px;
  border-bottom: 1px solid var(--line);
}

.filter-group {
  display: flex;
  gap: 4px;
}

.filter-chip {
  min-height: 32px;
  padding: 4px 9px;
  color: var(--muted);
  font-size: 11px;
}

.filter-chip.active {
  border-color: var(--running);
  color: var(--text);
