}

@media (max-width: 980px) and (min-width: 760px) {
  .command-rail {
    grid-template-columns: 1fr 1.4fr 1.2fr;
  }

  .rail-counters {
    grid-column: 1 / -1;
    grid-template-columns: repeat(4, 1fr);
    min-height: 44px;
    padding-block: 7px;
  }

  .workspace {
    grid-template-columns: minmax(230px, 5fr) minmax(280px, 5fr) minmax(180px, 2.5fr);
  }
}

@media (max-width: 759px) {
  body {
    overflow: auto;
  }

  .app-shell {
    display: block;
    height: auto;
    min-height: 100dvh;
  }

  .command-rail {
    position: static;
    grid-template-columns: 1fr 1fr;
  }

  .command-rail > * {
    min-height: 82px;
    padding: 10px 12px;
    border-bottom: 1px solid var(--line);
  }

  .metric-value {
    font-size: 16px;
  }

  .workspace {
    display: block;
  }

  .pane {
    border-right: 0;
    border-bottom: 1px solid var(--line-strong);
  }

  .fleet-grid {
    max-height: none;
    overflow: visible;
  }

  .transcript-pane {
    min-height: 55vh;
    grid-template-rows: auto minmax(55vh, 1fr) auto;
  }

  .transcript-feed {
    min-height: 55vh;
    max-height: 70vh;
  }

  .transcript-header > .mobile-anchor,
  .card-jump {
    display: inline-block;
  }

  .control-pane {
    min-height: 360px;
    overflow: visible;
  }

  .design-control-panel > .mobile-anchor {
    display: inline-block;
  }

  .bottom-rail {
    position: static;
    flex-wrap: wrap;
  }

  .utility-menu {
    margin-left: 0;
  }

  .bottom-provenance {
    margin-left: auto;
  }

  .routing-drawer {
    max-height: none;
  }
}

@media (max-width: 420px) {
  .command-rail > * {
    min-width: 0;
  }

  .rail-spend,
  .rail-burn {
    grid-template-columns: 1fr;
  }

  .provenance {
    justify-self: start;
  }

  .fleet-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .transcript-row {
    grid-template-columns: 1fr;
  }

  .row-meta {
    display: flex;
    gap: 8px;
  }

  .row-details {
    grid-column: 1;
  }

  .design-launcher-grid,
  .form-actions,
  .design-stream-actions {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

